def factorial(n):
    # Base case
    if n == 0:
        return 1
    # Recursive case
    return n * factorial(n - 1)

def sum_natural(n):
    # Base case
    if n == 0:
        return 0
    # Recursive case
    return n + sum_natural(n - 1)

# Read input
n = int(input())
print("Factorial:", factorial(n))
print("Sum:", sum_natural(n))

def fibonacci(n):
    if n == 0:
        return 0
    if n == 1:
        return 1
    return fibonacci(n - 1) + fibonacci(n - 2)

def power(base, exp):
    if exp == 0:
        return 1
    return base * power(base, exp - 1)

n = int(input())
base = int(input())
exp = int(input())

print("Fibonacci:", fibonacci(n))
print("Power:", power(base, exp))

def is_palindrome(s):
    if len(s) <= 1:
        return True
    if s[0] != s[-1]:
        return False
    return is_palindrome(s[1:-1])

def gcd(a, b):
    if b == 0:
        return a
    return gcd(b, a % b)

text = input().strip()
num1, num2 = map(int, input().split())

print("Palindrome:", is_palindrome(text))
print("GCD:", gcd(num1, num2))
